css:
/* Debate Floor — generated by NoaCG Studio. Edit freely: this file is yours. */

/* ── Style contract: change these variables to retint the whole graphic. ── */
:root {
  --accent: #e8c547;           /* the one accent color */
  --text-color: #ffffff;          /* primary text */
  --text-dim: rgba(255,255,255,0.72);  /* secondary text (title line) */
  --panel-bg: rgba(12, 14, 18, 0.92);  /* the panel behind the text */
  --font-heading: "Inter", Arial, sans-serif;  /* the graphic's typeface */
  --scale: 1;                  /* whole-graphic size multiplier (also handles resolution) */
  --type-scale: 1;                  /* text-only size multiplier (on top of --scale) */
  --font-numeric: var(--font-heading);          /* the typeface live numbers are set in (equal-width digits) */
}

/* Bundled open-source font (the file ships with the export — no internet at playout). */
@font-face {
  font-family: "Inter";
  src: url("fonts/inter.woff2") format("woff2");
  font-weight: 400 800;  /* variable font: covers this weight range */
  font-display: swap;          /* show fallback text until the font loads */
}
@font-face {
  font-family: "Inter";
  src: url("fonts/inter-latin-ext.woff2") format("woff2");
  font-weight: 400 800;  /* variable font: covers this weight range */
  font-display: swap;
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;  /* latin-ext: Š Ž Ł ő ğ and the rest of Latin Extended */
}

/* Reset and a transparent canvas (broadcast graphics render over video). */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;                /* nothing ever scrolls on air */
  background: transparent;
  font-family: var(--font-heading);
}

/* ── Root position (anchor zone) ── */
.scoreboard {
  position: absolute;
  left: calc(50% + 0px);           /* anchored to the horizontal center */
  bottom: 119px;                   /* inset from the bottom — wrapped text grows upward */
  transform: translateX(-50%);     /* center on the anchor point */
  text-align: center;              /* lines align toward the anchor edge */
  opacity: 0;                      /* hidden until play() runs the entrance */
}

/* ── The stage: the bar keeps its own width and the names fit inside it. ── */
.scoreboard-box {
  --stage-width: 1320px;      /* the room this bar was drawn for — this panel's width is the design's, never the text's */
  width: 1320px;  /* fallback: no CSS min() before Chromium 79 (older CasparCG) */
  width: min(calc(1320px * var(--scale)), 1680px);
  box-sizing: border-box;          /* the declared width includes the panel's own padding */
  justify-content: center;       /* short content leaves the room where the anchor already reads */
  max-width: 1680px;  /* fallback: no CSS min() before Chromium 79 (older CasparCG) */
  max-width: min(calc(1152px * var(--scale)), 1680px);  /* the wrap cap — follows --scale, stops at the safe area */
  will-change: transform, opacity; /* hint the browser: this element animates */
}
.scoreboard-mask {
  overflow: hidden;                /* lines animate in from behind this mask */
}
.scoreboard-mask > span {
  display: inline-block;           /* so the line can move (and pop) inside its mask */
  overflow-wrap: anywhere;         /* a word too long for its mask breaks: break-word cannot narrow the line, so the mask cut its end off */
  text-wrap: balance;              /* wrapped rows get even lengths */
}


/* Hidden data sources — holders SPX writes into and the runtime reads, never drawn.
   The rule lives in the stylesheet on purpose: an inline display:none would be wiped by the
   editor's entrance reset (it clears inline props) and the value would appear on screen. */
.noacg-data-source {
  display: none;                   /* input only: written by SPX, read by JS, never rendered */
}

/* ── Design ── */
/* The board itself — a flat panel, no blur: a school hall's camera has enough to do. */
.scoreboard {
  /* A PENALTY IS A SEMANTIC COLOUR, not a palette one. It has to read as "seconds were taken
     away" in every palette this design can be retinted into, so it is declared here on the
     design's own root rather than mixed from --accent, exactly as the alert levels are
     (templates/alerts/shared.ts). It is scoped to .scoreboard, never to :root, because the
     :root contract is the Style panel's and this is not one of its knobs. */
  --penalty-color: #ff5b52;
  /* One hairline weight, mixed from the text colour so it follows a retint. */
  --debate-hairline: color-mix(in srgb, var(--text-color) 16%, transparent);
}

.scoreboard-box {
  padding: calc(24px * var(--scale)) calc(44px * var(--scale)) calc(30px * var(--scale));
  background: var(--panel-bg);     /* the one panel behind everything */
  display: flex;
  flex-direction: column;
}

/* ── The round line ───────────────────────────────────────────────────────── */
/* Spacing is MARGINS, not flex `gap`: an older playout engine drops the gap declaration
   outright and the head would come up with everything touching. */
.scoreboard-head {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;                 /* a long round label takes a second row rather than pushing */
  margin-bottom: calc(12px * var(--scale));
  max-width: 100%;
}

.scoreboard-head > * {
  margin: calc(5px * var(--scale)) calc(9px * var(--scale));
}

.scoreboard-roundgroup {
  display: flex;
  align-items: center;
  min-width: 0;                    /* let the label wrap inside the group rather than push it */
}

/* The pip — a small turned square, the board's one drawn mark. */
.scoreboard-pip {
  flex: none;
  width: calc(12px * var(--scale));
  height: calc(12px * var(--scale));
  margin-right: calc(14px * var(--scale));
  background: var(--accent);
  transform: rotate(45deg);
}

.scoreboard-round {
  font-size: calc(26px * var(--scale) * var(--type-scale));
  font-weight: 600;
  letter-spacing: 0.2em;           /* tracked wide — it reads as a label, not a headline */
  text-transform: uppercase;
  color: var(--text-dim);
  max-width: calc(760px * var(--scale));
  /* LEFT, against the centred head, because the pip is the label's left anchor. A long motion
     that reaches the max-width above would otherwise centre itself inside a full-width box and
     drift away from the mark, leaving the pip stranded at the edge of the board. A short label
     shrinks to its own text, so the two read as one lockup either way. */
  text-align: left;
}

/* CENTRED, not baseline-aligned, and that is a real CSS trap rather than a taste call: a block
   with `overflow: hidden` — which every .scoreboard-mask is, so the presets can slide their
   lines in from behind one — synthesizes its baseline from its BOTTOM MARGIN EDGE instead of
   from the text inside it. Two masks of different type sizes therefore line up bottom-edge to
   bottom-edge, which drops the smaller word below the chip's border and clips it. Centring the
   two masks is immune to that, because it never asks either box for a baseline. */
.scoreboard-allowance {
  display: flex;
  align-items: center;
  padding: calc(4px * var(--scale)) calc(14px * var(--scale)) calc(6px * var(--scale));
  border: calc(2px * var(--scale)) solid var(--debate-hairline);
  max-width: 100%;
}

.scoreboard-allowance .scoreboard-mask + .scoreboard-mask {
  margin-left: calc(8px * var(--scale));
}

/* The second half of the same trap. The assembler makes every masked line an inline-block, and
   an inline-block sits on its line's BASELINE — so the mask's own strut (inherited font size,
   not the span's) pushes a smaller word down inside a box sized to the word, and `overflow:
   hidden` then cuts the descenders off. `vertical-align: top` puts the span at the top of its
   line box instead, where the mask's height already is. */
.scoreboard-allowance .scoreboard-mask > span {
  vertical-align: top;
}

.scoreboard-allowance-time {
  font-family: var(--font-numeric);  /* a face whose digits are all one width */
  font-variant-numeric: tabular-nums;  /* every digit the same width — no jitter on the tick */
  font-size: calc(26px * var(--scale) * var(--type-scale));
  font-weight: 700;
  color: var(--text-color);
}

.scoreboard-allowance-word {
  font-size: calc(24px * var(--scale) * var(--type-scale));
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-dim);
}

/* ── The two sides ────────────────────────────────────────────────────────── */
.scoreboard-body {
  display: flex;
  align-items: stretch;
}

/* `flex: 1 1 0` — not `1 1 auto` and not a basis in px. The halves are equal because the
   basis is ZERO for both, so neither speaker's name can buy width from the other; `min-width: 0`
   is what lets a long name actually wrap inside its own half instead of forcing the column
   wider (a flex item's default min-width is its content). */
.scoreboard-side {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  /* The whole column agrees: side, speaker and clock all read from the same edge. Without this
     a wrapped speaker name centres itself (the head's alignment is inherited) while the label
     above and the clock below stay flush, and the half reads as three loose parts. */
  text-align: left;
  padding-top: calc(16px * var(--scale));
}

.scoreboard-side .scoreboard-mask + .scoreboard-mask {
  margin-top: calc(6px * var(--scale));
}

/* Side B mirrors: the two halves read outward from the centre line. */
.scoreboard-side-b {
  align-items: flex-end;
  text-align: right;
}

/* The floor marker. It rests at a stub and grows to full width for whoever is speaking — the
   machine's floor group animates scaleX, so the board says who has the floor without a word. */
.scoreboard-rail {
  width: 100%;
  height: calc(6px * var(--scale));
  margin-bottom: calc(12px * var(--scale));
  background: var(--accent);
  transform-origin: left center;
  transform: scaleX(0.14);
  opacity: 0.3;
}

.scoreboard-rail-b { transform-origin: right center; }

.scoreboard-role {
  font-size: calc(25px * var(--scale) * var(--type-scale));
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.scoreboard-name {
  font-size: calc(46px * var(--scale) * var(--type-scale));
  font-weight: 700;
  line-height: 1.06;
  letter-spacing: -0.005em;
}

/* The clocks. Tabular figures so the half does not twitch four times a second, and the colour
   is set by the engine (accent while running, --penalty-color when docked or spent). */
.scoreboard-time {
  font-family: var(--font-numeric);  /* a face whose digits are all one width */
  font-variant-numeric: tabular-nums;  /* every digit the same width — no jitter on the tick */
  /* The tight leading below means the mask hides ~3px of the line box's descent space, which the
     overflow sweep records as a self-clip — correctly, and by design here: this mask only ever
     holds digits and a colon, none of which put ink below the baseline. The reveal masks are
     what the sweep's own header calls the by-design case, and the row is in its baseline. */
  font-size: calc(96px * var(--scale) * var(--type-scale));
  font-weight: 700;
  line-height: 1.04;
  color: var(--text-color);
  transition: color 0.2s linear;
}

/* ── The centre ───────────────────────────────────────────────────────────── */
.scoreboard-split {
  position: relative;
  flex: none;                      /* the divider is a fixed rule — it never takes half's width */
  width: calc(3px * var(--scale));
  margin: 0 calc(44px * var(--scale));
  background: var(--debate-hairline);
}

/* The penalty badge — the machine's penalty group flashes it on the centre line, so it belongs
   to neither side while naming what just happened to one of them. */
.scoreboard-penalty {
  position: absolute;
  top: calc(96px * var(--scale));
  left: 50%;
  transform: translateX(-50%);
  padding: calc(6px * var(--scale)) calc(18px * var(--scale));
  border: calc(2px * var(--scale)) solid var(--penalty-color);
  border-radius: calc(999px * var(--scale));
  background: var(--panel-bg);
  font-family: var(--font-numeric);  /* a face whose digits are all one width */
  font-variant-numeric: tabular-nums;  /* every digit the same width — no jitter on the tick */
  font-size: calc(30px * var(--scale) * var(--type-scale));
  font-weight: 700;
  color: var(--penalty-color);
  white-space: nowrap;
  opacity: 0;                      /* the penalty group fades it in and back out */
}

/* The accent rule under the whole board — the line-reveal preset draws this in first. */
.scoreboard-accent {
  width: 100%;
  height: calc(7px * var(--scale));
  background: var(--accent);
  transform-origin: left center;
}

js:
// Debate Floor — generated by NoaCG Studio. SPX calls update(), play(), stop(), next().

var onAir = false;               // true between play() and stop() — pops only happen on air
var scoreIds = [];     // the fields that pop when they change on air

// motionSpeed(): the template's speed knob. The NOACG_ANIM data block owns it; a legacy
// animSpeed variable is honored too, and hand-written animation code defaults to 1.
function motionSpeed() {
  if (typeof NOACG_ANIM !== 'undefined' && NOACG_ANIM.speed) return NOACG_ANIM.speed;
  if (typeof animSpeed !== 'undefined' && animSpeed) return animSpeed;
  return 1;
}

// Write one field value into its element. Text fields get plain
// text (operator input never runs as HTML); an <img id="fN"> gets the value as its image path.
function setFieldValue(el, value) {
  if (el.tagName === 'IMG') {
    if (value) { el.src = value; el.style.display = ''; }
    else { el.removeAttribute('src'); el.style.display = 'none'; }  // empty = show the design's placeholder
    // The img's parent gets .has-image so the CSS can hide a placeholder mark, resize, etc.
    if (el.parentNode && el.parentNode.classList) el.parentNode.classList.toggle('has-image', !!value);
  } else if (el.tagName === 'image') {
    // An SVG picture slot (an imported design's own <image> layer): swap its href. Empty
    // restores the picture the designer drew, so an untouched field changes nothing.
    if (!el.hasAttribute('data-orig-href')) el.setAttribute('data-orig-href', el.getAttribute('href') || '');
    el.setAttribute('href', value || el.getAttribute('data-orig-href'));
  } else {
    el.textContent = value;
  }
}

// update(data): SPX sends field values as JSON, e.g. {"f0":"HOME","f1":"2"}.
// Each value is written into the element whose id matches the field name (f0 -> id="f0").
// A score that CHANGES while on air gets a pop: scale up, then spring back down.
function update(data) {
  var fields = (typeof data === 'string') ? JSON.parse(data) : data;
  for (var key in fields) {
    var el = document.getElementById(key);
    if (!el) continue;
    var changed = el.textContent !== String(fields[key]);  // textContent: exactly what the operator typed
    setFieldValue(el, fields[key]);
    // A CHANGED value in the CLOCK element is a correction to the running clock, not just
    // text — re-seed the tick from it, or the next second would overwrite the fix. An
    // UNCHANGED one is the wire resending the cue's whole value set (a score bump), and
    // matchClockUpdate repaints the ticked time over what setFieldValue just wrote above.
    if (typeof matchClockUpdate === 'function') matchClockUpdate(key, fields[key]);
    // A board that runs CLOCKS OF ITS OWN (the debate floor's two) adopts the wire's value on
    // the same beat and by the same rule: a stamped value says a clock is running and when it
    // read that time, a plain one is a held time or the chair's correction, and a resend of the
    // cue's own text is neither. Guarded, so every other board emits nothing extra.
    if (typeof speakingClockUpdate === 'function') speakingClockUpdate(key, fields[key]);
    if (changed && onAir && scoreIds.indexOf(key) !== -1) {
      // Pop the MASK (the span's parent), not the span: the span is clipped by the mask's
      // overflow:hidden, so scaling it would chop the outer digits of a two-digit score.
      // Scaling the mask scales its clip region together with the digits — nothing is cut.
      // No preset ever tweens a mask, so the pop can't collide with an entrance or exit.
      gsap.fromTo(el.parentNode,
        { scale: 1.35 },
        { scale: 1, duration: 0.4 / motionSpeed(), ease: 'back.out(1.7)' }
      );
    }
  }
  // Row-based boards (a period breakdown, a set-by-set line) re-render from their hidden
  // source; a plain scorebug defines no rebuild, so it is only called when it exists.
  if (typeof rebuildScoreboard === 'function') rebuildScoreboard();
  paintMatchState();
  // Designs on a stage hold their lines to the rows they were drawn for (no-op otherwise).
  if (typeof fitStagedText === 'function') fitStagedText();
}

// paintMatchState(): make the board's LOOK agree with the machine's state.
//
// The interval and full-time treatments are CLASSES on the root, and a class is the one thing
// a visual reset does not touch: noacgResetGraphic clears inline props, and noacgSnap replays
// states with callbacks suppressed AND skips any group already at its initial - so the call
// that would have removed the class never runs. Left alone, a board recovered mid-match comes
// back still wearing FULL TIME while the machine reports it live, which is the same recovery
// lie the quiz board's repaint fixed (see paintQuizState in quiz/shared.ts).
//
// Repainting from the machine rather than clearing unconditionally is what makes it safe to
// call on every update: a genuinely finished board keeps its treatment while an operator edits
// the score, and only a board whose machine says otherwise loses it.
function paintMatchState() {
  if (typeof noacgMachineState !== 'function') return;   // a design with no machine has no state to paint
  var root = document.querySelector('.scoreboard');
  if (!root) return;
  var groups = (noacgMachineState() || {}).groups || {};
  var atBreak = false;
  var atFinal = false;
  // Read every group by VALUE, not by name: the two-team boards carry the interval and the
  // result as separate parallel groups, the status card carries both in one - and both spell
  // the states the same way, so neither shape needs a special case here.
  for (var id in groups) {
    if (groups[id] === 'interval') atBreak = true;
    if (groups[id] === 'final') atFinal = true;
  }
  root.classList.toggle('scoreboard-break', atBreak && !atFinal);
  root.classList.toggle('scoreboard-final', atFinal);
}

// play(): take the scoreboard on air — run the entrance timeline.
function play() {
  gsap.killTweensOf('*');          // stop any animation that is still running
  resetScorePop();                 // a killed mid-pop score must not enter enlarged
  onAir = true;
  buildInTimeline();
}

// stop(): take the scoreboard off air — run the exit timeline.
function stop() {
  gsap.killTweensOf('*');
  resetScorePop();                 // don't freeze a half-finished pop at scale > 1
  onAir = false;
  // A board that RUNS something (the debate floor's speaking clocks) has to be told the
  // graphic is going down, or its interval outlives the thing it was painting — the same leak
  // the scoreboard type's comment records from a clock group whose element was not there.
  // Defined only by a design that has something to stop, so a plain scorebug emits no call
  // site's worth of behaviour it does not need. There is no play() twin here: a board comes up in
  // its machine's initial state, and starting something is what an operator event is for. One
  // with something still running through a Take keeps it itself (debateFloor.ts).
  if (typeof boardOffAir === 'function') boardOffAir();
  buildOutTimeline();
}

// resetScorePop(): killTweensOf() can freeze a score mid-pop at scale ~1.x; the
// entrance/exit timelines never touch the masks, so snap both score masks back to 1 here.
function resetScorePop() {
  for (var i = 0; i < scoreIds.length; i++) {
    var el = document.getElementById(scoreIds[i]);
    if (el) gsap.set(el.parentNode, { scale: 1 });  // the mask is what update() pops
  }
}

// next(): SPX Continue — advance one step along the default path. This design ships
// single-step, so it normally does nothing; it still funnels to the interpreter so a
// template that GROWS a step (or a state machine) stays drivable through the SPX contract.
function next() {
  return (typeof revealNextStep === 'function') ? revealNextStep() : null;
}

// This board runs its own clocks (below) — the shared single-clock match runtime is not emitted.

// ---- The debate floor's two clocks (playout, not motion — the machine calls into this) ----
// One clock runs at a time: whoever holds the floor. The truth about how much time a speaker
// has left is the number ON SCREEN, which is also the field the chair can retype mid-debate.
var DEBATE_TICK_MS = 250;        // four times a second — a retyped correction is adopted fast
var debateTimer = null;          // the repaint interval while a clock runs, else null
var debateActive = null;         // 'a', 'b', or null when nobody holds the floor
var debateDeadline = 0;          // ms timestamp the running count is anchored to
var debateLastPaint = { a: '', b: '' };   // what WE last wrote (anything else is the operator)
var debateExpired = { a: false, b: false };
var debateDocked = null;         // the side wearing a just-taken penalty, or null
var debateOffAir = false;        // the board has gone down, and no Take or snap has brought it back

function debateClockEl(side) { return document.getElementById(side === 'a' ? 'f5' : 'f6'); }

// WHEN the thing that is happening happened. Inside an operator event forwarded by a renderer
// this is the log row's own server time — the same instant every renderer of the production
// reads — and outside one it is simply now. Anchoring a speech to it rather than to this
// browser's clock is what stops two browser sources of the same debate drifting apart, and what
// lets a renderer replaying a missed row resume the speech from where it really started instead
// of from the moment it caught up.
function debateNow() {
  return (typeof noacgEventAt === 'number' && noacgEventAt > 0) ? noacgEventAt : Date.now();
}

// The value without its origin stamp — what a person reads, and what a held clock carries.
// The stamp is OURS, not the chair's, so it is this half a resend is judged against.
function debatePlainTime(text) {
  var raw = String(text == null ? '' : text);
  var at = raw.indexOf('@');
  return (at === -1 ? raw : raw.slice(0, at)).replace(/\s+/g, '');
}

// The epoch ms an "@"-stamped value was true, or 0 for a plain (held) one. A stamp that is not
// a number reads as absent: a broken stamp must degrade to a held clock showing the right time,
// never to one counting from 1970.
function debateWireOrigin(text) {
  var raw = String(text == null ? '' : text);
  var at = raw.indexOf('@');
  if (at === -1) return 0;
  var stamp = parseInt(raw.slice(at + 1), 10);
  return stamp > 0 ? stamp : 0;
}

// "05:00" -> 300 · "5:00" -> 300 · "300" -> 300 (a bare number is seconds). Anything else is 0,
// which is how a half-typed value stops the count instead of racing to a nonsense deadline.
function debateParseTime(text) {
  var raw = debatePlainTime(text);
  if (!raw) return 0;
  var parts = raw.split(':');
  var total;
  if (parts.length === 1) {
    if (!/^\d+$/.test(parts[0])) return 0;
    total = parseInt(parts[0], 10);
  } else {
    if (!/^\d+$/.test(parts[0]) || !/^\d+$/.test(parts[1])) return 0;
    total = parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
  }
  return total > 0 ? total : 0;
}

// Is this text a time at all? "00:00" and "3:x" both parse to zero, and they must not be treated
// alike: one is a clock that has run out, the other a half-finished edit to leave alone.
function debateIsTime(text) {
  var raw = debatePlainTime(text);
  return /^\d+$/.test(raw) || /^\d+:\d+$/.test(raw);
}

function debateFormat(total) {
  var pad = function (n) { return n < 10 ? '0' + n : String(n); };
  return pad(Math.floor(total / 60)) + ':' + pad(total % 60);
}

// Paint one side's remaining time, and remember that it is out of time when it is.
function debatePaint(side, seconds) {
  var left = Math.max(0, seconds);
  var el = debateClockEl(side);
  if (el) {
    el.textContent = debateFormat(left);
    debateLastPaint[side] = el.textContent;
  }
  debateExpired[side] = left <= 0;
  debatePaintClockColors();
}

function debateRemaining(side) {
  var el = debateClockEl(side);
  return debateParseTime(el ? el.textContent : '');
}

// The allowance each speaker gets, and the size of one penalty.
function debateAllowance() {
  var el = document.getElementById('f7');
  var seconds = debateParseTime(el ? el.textContent : '');
  return seconds > 0 ? seconds : 300;
}

function debatePenaltySeconds() {
  var el = document.getElementById('f9');
  var seconds = parseInt(el ? String(el.textContent).replace(/\s+/g, '') : '', 10);
  return seconds > 0 ? seconds : 10;
}

// Whose clock is running is said in COLOUR: the accent while it runs, the danger colour when it
// has just been docked or has run out, plain text otherwise. The machine's states carry the same
// colours as keyframes, so a parked or thumbnailed frame is right with no clock running at all;
// the engine re-asserts them here whenever the truth underneath changes.
function debateClockColorFor(side) {
  if (debateExpired[side] || debateDocked === side) return 'var(--penalty-color)';
  return (debateActive === side && debateTimer) ? 'var(--accent)' : 'var(--text-color)';
}

function debatePaintClockColors() {
  var sides = ['a', 'b'];
  for (var i = 0; i < sides.length; i++) {
    var el = debateClockEl(sides[i]);
    if (el) el.style.color = debateClockColorFor(sides[i]);
  }
}

function debateStopTimer() {
  if (debateTimer) { clearInterval(debateTimer); debateTimer = null; }
}

// One tick: recompute from the deadline rather than decrementing a counter, so nothing
// accumulates. If the number on screen is not the one we painted, the chair (or an update) has
// typed into the clock — adopt that as the new truth, and leave anything that is not a time
// exactly where they put it rather than overwriting a half-finished edit.
function debateTick() {
  if (!debateActive) return;
  var el = debateClockEl(debateActive);
  var shown = el ? String(el.textContent).replace(/\s+/g, '') : '';
  if (shown !== debateLastPaint[debateActive]) {
    var typed = debateParseTime(shown);
    if (typed <= 0) { debateStopTimer(); debatePaintClockColors(); return; }
    debateDeadline = Date.now() + typed * 1000;
  }
  var left = Math.max(0, Math.ceil((debateDeadline - Date.now()) / 1000));
  debatePaint(debateActive, left);
  if (left <= 0) { debateStopTimer(); debatePaintClockColors(); }
}

// Freeze whoever is speaking at the value on screen.
function debateHold() {
  if (debateActive && debateTimer) {
    debatePaint(debateActive, Math.max(0, Math.ceil((debateDeadline - debateNow()) / 1000)));
  }
  debateStopTimer();
}

// Give one side the floor: the other stops where it is, this one picks up from its OWN number.
// That is the whole point of two clocks — a speaker who is interrupted does not lose the time.
function debateStart(side) {
  // ALREADY RUNNING THIS SIDE: the wire got here first. On a hosted production the switch row's
  // clock values are written BEFORE the event that consumes them, so speakingClockUpdate has
  // already adopted the stamp and anchored the count to the row's own instant. Re-anchoring here
  // would subtract the elapsed time a second time, and on a REPLAYED row — a renderer catching
  // up on a speech that began minutes ago — that lands the clock at zero. The other way here is a
  // Take on air putting the floor back on the speaker still counting (below), which changes nothing
  // either.
  if (debateActive === side && debateTimer) { debatePaintClockColors(); return; }
  if (debateOffAir) return;
  debateHold();
  debateActive = side;
  var left = debateRemaining(side);
  debateDeadline = debateNow() + left * 1000;
  debatePaint(side, left);
  if (left > 0) debateTimer = setInterval(debateTick, DEBATE_TICK_MS);
  debatePaintClockColors();
}

function runSpeakerA() { debateStart('a'); }
function runSpeakerB() { debateStart('b'); }

// The exit's call: nobody holds the floor once the board is off air, and nobody takes it there. A
// Switch that reaches a board already down starts nothing; the wire ignores it too. Only a machine
// runtime can end that, below: a hand-written region has no such Take to bring the board back.
function holdClocks() {
  debateHold();
  debateActive = null;
  debateOffAir = typeof noacgMachinePlay === 'function';
  debatePaintClockColors();
}

// A TAKE ON AIR DOES NOT TAKE THE FLOOR AWAY. play() rests every machine group at its initial state,
// which for the floor is armed, but a speaker still counting through a Take has not stopped: this
// engine and the wire's stamp both say who it is. Left armed, the next Switch would start A whoever
// the wire handed the floor to, and the two would name different speakers from then on. So the floor
// goes straight back to that speaker. debateStart then finds that side already running and changes
// nothing, so this holds in a boot's recovery too, where play() follows the report's data with no
// data after it. A board that has been off air holds nobody, and neither does a first Take.
if (typeof noacgMachinePlay === 'function') {
  var debateMachinePlay = noacgMachinePlay;
  noacgMachinePlay = function () {
    debateOffAir = false;
    var entrance = debateMachinePlay();
    for (var g = 0; debateActive && g < noacgMachine.groups.length; g++) {
      if (noacgMachine.groups[g].id === 'floor') noacgFire(noacgMachine.groups[g], { to: debateActive === 'a' ? 'speakerA' : 'speakerB' });
    }
    return entrance;
  };
}

// A SNAP TO ARMED MEANS IT: nobody speaks, and each clock holds what it reads. A snap skips a group
// bound for its initial state, so armed's own call never runs and the count would outlive the pose.
// The wire banks the same row (control/matchClockWire.ts). The numbers are not reset: that is Reset.
if (typeof noacgSnap === 'function') {
  var debateMachineSnap = noacgSnap;
  noacgSnap = function (assignments, opts) {
    debateOffAir = false;
    var pose = debateMachineSnap(assignments, opts);
    if (debateActive && pose.groups.floor === 'armed') {
      debateStopTimer();
      debateActive = null;
      debatePaintClockColors();
    }
    return pose;
  };
}

// Both clocks back to the set allowance, nothing running — the reset button's whole job.
// RESET IS TWO OPERATIONS and this is the DATA half: it puts the numbers back. The floor group
// walking to its own armed state is the visual half, and the machine owns that.
function resetClocks() {
  debateStopTimer();
  debateActive = null;
  var full = debateAllowance();
  debatePaint('a', full);
  debatePaint('b', full);
  debatePaintClockColors();
  clearPenaltyMark();
}

// Dock the penalty from whoever is speaking. The running clock keeps running, just shorter —
// a penalty is a deduction, not a stoppage.
function applyPenalty() {
  var badge = document.querySelector('.scoreboard-penalty');
  var cost = debatePenaltySeconds();
  if (badge) badge.textContent = '-' + cost;
  if (!debateActive) return;
  var live = debateTimer
    ? Math.max(0, Math.ceil((debateDeadline - debateNow()) / 1000))
    : debateRemaining(debateActive);
  var left = Math.max(0, live - cost);
  debatePaint(debateActive, left);
  if (left > 0) debateDeadline = debateNow() + left * 1000;
  else debateStopTimer();
  debateDocked = debateActive;
  debatePaintClockColors();
}

// The penalty group's other state calls this when the flash is over.
function clearPenaltyMark() {
  debateDocked = null;
  debatePaintClockColors();
}

// ---- The wire's own clock values (control/matchClockWire.ts) ----
//
// speakingClockUpdate(key, value): called from update() for every field written, and the one
// place a clock's value ARRIVING is read. Three kinds reach it, told apart by the "@" stamp:
//
//   "03:12@1755600000000"  a RUNNING clock: it read 03:12 at that instant, and this side holds
//                          the floor. Adopt both — the derived time is right however long ago
//                          that was, which is what brings a reconnecting browser source back
//                          mid-speech instead of at the allowance.
//   "03:12"                a HELD time: the wire banking a stopped clock, or the chair typing a
//                          correction into a running one.
//   "04:00@/05:00/05:00"   the same held time on /output, after the time it also carries what the
//                          cue last sent, which is the wire's to read. A stamped value carries it
//                          too. Every parser here stops at the "@" or the "/", so it reads as above.
//   a plain value equal to the last one delivered — a RESEND, not an edit. Every Take, ✎ Update
//                          and Snap sends the cue's WHOLE value set, and a cue stores the plain
//                          allowance forever, so a penalty in the fourth minute re-sends
//                          "05:00" over a clock that has run down to 01:12. Adopting that would
//                          pull the speech back to full time on every press.
//
// It is the PLAIN HALF that is compared, for the reason the match clock states at length: the
// stamp is ours, and the chair's "05:00" has not changed just because we stamped it. The honest
// limit is the same one too — the chair cannot re-apply a time the clock already holds, and
// returning to a known figure is what Reset is for.
var debateSent = { a: null, b: null };   // the last value the WIRE delivered, not the painted time

function debateSideOfField(key) {
  if (key === 'f5') return 'a';
  if (key === 'f6') return 'b';
  return null;
}

// Put the side's REAL time back on screen. setFieldValue has already written the wire's raw text
// into the element for every field alike, so a stamped value would otherwise sit on air reading
// "03:12@1755600000000", and a resent one would show a stale time until the next tick.
function debateRepaintSide(side) {
  if (debateActive === side && debateTimer) {
    debatePaint(side, Math.max(0, Math.ceil((debateDeadline - Date.now()) / 1000)));
  } else {
    debatePaint(side, debateParseTime(debateLastPaint[side]));
  }
}

function speakingClockUpdate(key, value) {
  var side = debateSideOfField(key);
  if (!side) return;
  var incoming = String(value == null ? '' : value);
  var origin = debateWireOrigin(incoming);
  if (!origin && debateSent[side] !== null && debatePlainTime(incoming) === debatePlainTime(debateSent[side])) {
    debateRepaintSide(side);
    return;
  }
  debateSent[side] = incoming;
  var base = debateParseTime(incoming);
  if (origin) {
    // The wire says this side is running, and what it read when. Anchoring to the origin rather
    // than to this browser is what makes two browser sources of the same debate paint the same
    // second, and what lets a renderer that boots mid-speech land on the right one.
    debateStopTimer();
    debateActive = side;
    var left = Math.max(0, base - Math.max(0, Math.floor((Date.now() - origin) / 1000)));
    debateDeadline = Date.now() + left * 1000;
    debatePaint(side, left);
    if (left > 0) debateTimer = setInterval(debateTick, DEBATE_TICK_MS);
    debatePaintClockColors();
    return;
  }
  // Not a time at all — a half-finished edit in the studio's Content panel. Leave it exactly
  // where the chair put it and stop counting; their text is theirs.
  if (!debateIsTime(incoming)) {
    if (debateActive === side) debateStopTimer();
    debatePaintClockColors();
    return;
  }
  // A plain time. Held, unless this side is the one speaking — in which case it is the chair
  // correcting a running clock, which must correct it without stopping it.
  debatePaint(side, base);
  if (debateActive !== side) return;
  if (base <= 0) { debateStopTimer(); debatePaintClockColors(); return; }
  debateDeadline = Date.now() + base * 1000;
  if (!debateTimer) { debateTimer = setInterval(debateTick, DEBATE_TICK_MS); debatePaintClockColors(); }
}

// Show the allowance on both clocks before the first play(), so a preview and the studio's
// parked view look like the board will. This file loads in <head> — wait for the DOM.
function paintIdleDebateClocks() {
  var full = debateAllowance();
  debatePaint('a', full);
  debatePaint('b', full);
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', paintIdleDebateClocks);
} else {
  paintIdleDebateClocks();
}

// A retyped clock, a resend of the cue's own allowance and the wire's origin-stamped running
// time all arrive through update(), and the engine tells them apart per FIELD — so this board
// needs no rebuildScoreboard() hook; speakingClockUpdate() is the one it answers.

// This one runs when the board goes off air. Nobody holds the floor once the graphic is down,
// and the tick must not outlive the thing it paints.
function boardOffAir() { holdClocks(); }

// Hold every line to the room this design gives it, so the panel never grows taller than
// it was drawn. Called after each update() (see update() above) and once the fonts are in.
//
// The room is measured ONCE, from the design's own sample text, and remembered on the element:
// that is "the rows this line was drawn for". Everything the operator types afterwards is fitted
// into it by reducing the font size, never past STAGE_FIT_MIN of the design size.
var STAGE_FIT_MIN = 0.55;        // never shrink below 55% of the size the design asks for
// …and never below the CATALOG'S OWN TYPE FLOOR either, whatever the design size was. 55% of a
// 32px letter is 17.6px, which is under the 20px this catalogue holds every graphic to
// (scripts/type-floor.mjs, DESIGN_LANGUAGE §1) - so the relative floor alone let the fit shrink
// text into illegibility and the type-floor gate caught four variants doing it. Past this point
// a tight line is the better failure: the words stay readable and the panel still holds.
var STAGE_FIT_FLOOR_PX = 20;
var stageCalibrated = false;     // true once the design's own sample has been measured

// A RESERVE IS A LAYOUT NUMBER, AND A RECT IS THE VISUAL BOX - the two stop agreeing the moment
// anything above the line is TRANSFORMED. `getBoundingClientRect` reports the box after every
// ancestor transform has been applied, so a line inside a CSS-animated badge is measured through
// whatever that animation was doing on the frame the fit happened to run. Both halves of that were
// shipping (measured 2026-08-23/24, on the run that made e2e/catalog-baseline.spec.ts flake with a
// DRIFTING element set - nothing about the graphics had moved, the measurement had):
//
//   - gt03's badge SCALES as it pops, so its clock reserved 412px, 417px and 418px across three
//     runs for an element that is 400px in layout - the reserve was the pop, frozen at whatever
//     moment the fit landed on.
//   - gt04's badge only TRANSLATES, which should cost nothing - but the rect still comes back
//     through the composited matrix, so its height alternates between 399.9999694824219 and
//     400.0000305175781 from frame to frame, and `Math.ceil` turns that into 400 or 401.
//
// So the reserve is read off the LAYOUT box instead. `getComputedStyle().height` is the used
// height in px - sub-pixel, and blind to transforms, which is exactly the difference that matters
// (`offsetHeight` is blind to them too but rounds to a whole pixel, and a reserve rounded DOWN is
// a clipped design). It is the content box unless the element says otherwise, so the padding and
// border are added back to keep this the border box the rest of this file measures in.
//
// Snapped to 1/64 px, Blink's own layout unit, so a used value that comes back with a float tail
// still lands on one number every time. A genuine sub-pixel reserve (188.5) is untouched and still
// rounds up to a whole 189 where the caller asks for that.
function stageLayoutHeight(el, cs) {
  var h = parseFloat(cs.height);
  if (!(h >= 0)) return Math.round(el.getBoundingClientRect().height * 64) / 64;  // not laid out
  if (cs.boxSizing !== 'border-box') {
    h += (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0) +
      (parseFloat(cs.borderTopWidth) || 0) + (parseFloat(cs.borderBottomWidth) || 0);
  }
  return Math.round(h * 64) / 64;
}

// THE PANELS THIS RUNTIME LOOKS AFTER, kept in a shared list rather than baked into each
// function as one selector.
//
// It matters when a graphic is INSERTED into another (blocks/templateInsert.ts). Both templates
// carry this same runtime, so the merged file declares these functions twice and the later
// declaration wins - and if each copy had its own hardcoded selector, the losing graphic would
// silently stop being fitted. Registering the selector instead means whichever copy survives
// still fits BOTH panels, which is what makes the duplicate harmless rather than quietly
// destructive. It is also why these names can sit in that file's scaffold allowlist honestly:
// they are assembler scaffolding, like setFieldValue, not design-owned logic.
var STAGE_FIT_BOXES = (window.__noacgStageFitBoxes = window.__noacgStageFitBoxes || []);
if (STAGE_FIT_BOXES.indexOf('.scoreboard-box') < 0) STAGE_FIT_BOXES.push('.scoreboard-box');

function stageFitBoxes() {
  var found = [];
  for (var i = 0; i < STAGE_FIT_BOXES.length; i++) {
    var els = document.querySelectorAll(STAGE_FIT_BOXES[i]);
    for (var j = 0; j < els.length; j++) found.push(els[j]);
  }
  return found;
}

// One row of this line, at the size the design asks for. `line-height: normal` computes to a
// keyword rather than a number on some faces, so fall back to the CSS default ratio.
function stageLineHeight(el, cs, design) {
  var line = parseFloat(cs.lineHeight);
  return (line && !isNaN(line)) ? line : design * 1.2;
}

// ONE ROW'S CONTENT HEIGHT for this element's face - a DIFFERENT box from the one above, and the
// distinction is the whole reason this function exists. `line-height` says how much room a row
// TAKES; the FACE decides how tall its own glyph box IS, and on most of the bundled faces that is
// about 1.2em whatever line-height says (measured: Space Grotesk 1.17, Inter 1.14, Manrope 1.24,
// Oswald 1.29, Saira 1.35). `scrollHeight` reads the second box, so a row drawn with the tighter
// line-height of the two reports an overflow that is not there and shrinks for nothing.
//
// Measured once per face and cached on the window, for the same reason the box list is: a board
// rebuilds its rows on every update, and a graphic inserted into another carries a second copy of
// this file. The probe is a zero-height, zero-leading box, so its scrollHeight is the glyph box
// and nothing else.
var STAGE_FACE_RATIOS = (window.__noacgStageFaceRatios = window.__noacgStageFaceRatios || {});
function stageFaceHeight(cs, design) {
  var key = cs.fontFamily + '|' + cs.fontWeight + '|' + cs.fontStyle;
  var ratio = STAGE_FACE_RATIOS[key];
  if (!ratio) {
    var probe = document.createElement('div');
    probe.style.cssText = 'position:absolute;left:-9999px;top:0;height:0;line-height:0;white-space:nowrap;visibility:hidden';
    probe.style.fontFamily = cs.fontFamily;
    probe.style.fontWeight = cs.fontWeight;
    probe.style.fontStyle = cs.fontStyle;
    probe.style.fontSize = '100px';
    probe.textContent = 'Hxpg';                 // an ascender, an x-height, two descenders
    document.body.appendChild(probe);
    ratio = probe.scrollHeight / 100;
    document.body.removeChild(probe);
    if (!(ratio > 0)) ratio = 1.2;              // a face that will not measure gets the CSS default
    STAGE_FACE_RATIOS[key] = ratio;
  }
  return ratio * design;
}

// EVERY LEAF TEXT ELEMENT inside the staged panel, not just the masked lines the presets
// choreograph. A poll's option rows, a standings board's names and a queue's entries are built by
// the design's own runtime from a textarea, so they carry no mask - and they are exactly where
// the remaining height came from once the masked lines were held. A leaf that already fits is
// left alone, so widening the net costs nothing on the designs that did not need it.
function stagedLines() {
  var boxes = stageFitBoxes();
  var all = [];
  for (var b = 0; b < boxes.length; b++) {
    var kids = boxes[b].querySelectorAll('*');
    for (var k = 0; k < kids.length; k++) all.push(kids[k]);
  }
  var out = [];
  for (var i = 0; i < all.length; i++) {
    var el = all[i];
    if (el.children.length) continue;                       // not a leaf: its children carry the text
    var text = (el.textContent || '').trim();
    if (!text) continue;                                    // nothing to fit
    // A one- or two-character leaf is a glyph, a letter chip or a single digit: it cannot
    // wrap, so it has no room to be held to - and reserving one clipped sn03's avatar, whose
    // icon sits inside a fixed circular frame that was never ours to resize.
    if (text.length < 3) continue;
    if (el.className && String(el.className).indexOf('noacg-data-source') >= 0) continue;
    // A DESIGN THAT ALREADY BOUNDS ITS OWN LINE IS LEFT ALONE. `-webkit-line-clamp` is the
    // author saying how many rows this line may have; imposing a reserve on top of that fights
    // a decision already made, and the audience pack's own gate caught it - a clamped question
    // ended up taller than the clamp allows. The rule is the one the stage follows everywhere:
    // where the design has stated the room, the runtime does not restate it.
    var clamp = window.getComputedStyle(el).webkitLineClamp;
    if (clamp && clamp !== 'none') continue;
    out.push(el);
  }
  return out;
}

function fitStagedText() {
  var lines = stagedLines();
  for (var i = 0; i < lines.length; i++) fitOneStagedLine(lines[i]);
  holdStageHeight();
}

// THE OUTER GUARANTEE. Fitting the lines is what SHOULD keep the panel its own size, and on a
// design whose text is all in lines it does. It is not enough on a board whose runtime rebuilds
// its own rows: the row elements are replaced wholesale on every update, so anything remembered
// on them is gone, and one reflow the fit did not see would move the panel again. Reserving the
// panel's own height closes that for good - measured once, from the design's own content, on the
// same terms as everything else here.
function holdStageHeight() {
  var boxes = stageFitBoxes();
  for (var i = 0; i < boxes.length; i++) holdOneStageBox(boxes[i]);
}

function holdOneStageBox(box) {
  var room = parseFloat(box.getAttribute('data-stage-room') || '');
  if (!room) {
    box.style.height = '';
    // The panel's own reserve reads the layout box for the same reason its lines do: a panel
    // whose content animates would otherwise reserve whatever that animation was mid-way through.
    room = stageLayoutHeight(box, window.getComputedStyle(box));
    if (!room) return;
    box.setAttribute('data-stage-room', room);
  }
  box.style.boxSizing = 'border-box';   // the reserve is the border box it was measured from
  // HEIGHT, and deliberately NOT overflow:hidden - the same lesson as the lines above, one
  // level up. The height is what holds the panel; hiding the overflow as well cut content on
  // 17 designs at their OWN default text. If a value ever beats the shrink floor it bleeds a
  // little rather than losing words, and the panel still has not moved.
  // A FLOOR, not a fixed height. The panel must not SHRINK when a value is short - that is the
  // wobble - but it has to be allowed to grow when a value is so long that the shrink hits the
  // 20px type floor and still does not fit. Pinning it there instead makes the runtime bench
  // fail with siblings overlapping by 71%: with the words held at a legible size and the panel
  // refusing to give, the only thing left to collide is the content.
  box.style.minHeight = room + 'px';
}

// THE WIDTH OF THE TEXT ITSELF, and deliberately NOT `scrollWidth`. A design's backdrop is often
// a pseudo-element that OVERHANGS its box on purpose - ss02's slab and chip both lean -8deg, and
// a skewed absolutely-positioned layer counts towards the element's scrollable overflow. So
// scrollWidth reported 936 against a 920px row and the runtime read a painted lean as the
// headline running out of its box: 92px shipped at 66px, at the design's own default words.
// A Range over the element's own text nodes measures letters and nothing else, and on a wrapped
// block its rects are the line boxes - so the widest ROW is what gets compared, which is the
// number that decides whether anything is actually outside the box.
function stageTextWidth(el) {
  if (!document.createRange) return el.scrollWidth;
  var range = document.createRange();
  range.selectNodeContents(el);
  var rects = range.getClientRects();
  var widest = 0;
  for (var i = 0; i < rects.length; i++) if (rects[i].width > widest) widest = rects[i].width;
  return widest || el.scrollWidth;
}

// The room across, on the same terms: the CONTENT box, since that is the box the text sits in.
// Taken from the RECT and not from `clientWidth`, because clientWidth is rounded to whole pixels
// and the text width beside it is not - and half a pixel on a chip 50px across is a 1% overflow
// that is not there. Seventeen designs sat just past the fit's 0.5% tolerance on nothing else.
// `clientWidth` still answers one question the rect cannot: an inline box reports 0 there, and an
// inline box has no content width to hold anything to.
function stageContentWidth(el, cs) {
  if (!el.clientWidth) return 0;
  var w = el.getBoundingClientRect().width
    - (parseFloat(cs.borderLeftWidth) || 0) - (parseFloat(cs.borderRightWidth) || 0)
    - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0);
  return w > 0 ? w : 0;
}

// THE BOX A LINE IS DRAWN IN, if it has one: the nearest ancestor that actually paints - a tile,
// a chip, a coloured severity square. That box is FURNITURE, and furniture does not stretch to fit
// a longer word; the words fit the furniture. Found by walking up rather than by class name, so it
// works on any design without being told which of its elements are boxes.
function drawnBoxOf(el) {
  for (var p = el.parentNode; p && p.nodeType === 1 && p !== document.body; p = p.parentNode) {
    var cs = window.getComputedStyle(p);
    var bg = cs.backgroundColor;
    if (cs.backgroundImage && cs.backgroundImage !== 'none') return p;
    if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') return p;
    if (parseFloat(cs.borderTopWidth) > 0 || parseFloat(cs.borderLeftWidth) > 0) return p;
  }
  return null;
}

// Everything this runtime pins on a line, taken back off. Used by the recalibration below, which
// has to put every line back to the design's own CSS BEFORE it measures any of them - the fit runs
// in document order, so anything still pinned is a sibling whose height is about to decide the
// reserve of the line being measured.
function stageUnpin(el) {
  el.style.fontSize = '';
  el.style.maxWidth = '';
  el.style.height = '';
  el.style.whiteSpace = '';
  el.style.overflowWrap = '';
  el.style.textAlign = '';
  el.style.display = '';
}

function fitOneStagedLine(el) {
  el.style.fontSize = '';                       // back to the design size before measuring
  el.style.maxWidth = '';
  var cs = window.getComputedStyle(el);
  var design = parseFloat(cs.fontSize);
  if (!design) return;

  // A LINE INSIDE A DRAWN BOX IS GOVERNED BY THAT BOX, not by its own calibrated reserve. The
  // reserve says "this line had one row when the design was drawn", which is the right rule for a
  // line standing on its own and the wrong one inside a tile: the tile has its own width and
  // height, and a label that outgrows them runs straight out of the colour. The owner caught
  // exactly this on the alert strip, where "ADVISORY" became "ADVISORY WISNIEWSKA" and left the
  // blue square on both sides - a defect every gate here missed, because they all measured
  // whether the PANEL moved and none asked whether the text stayed inside its own box.
  var box = drawnBoxOf(el);
